return {{["id"]=1,["name"]="The Grid",["source_label"]="The Grid",["source_version"]=6,["icon"]="virtual-signal/shape-cross",["category"]="Base Grid",["bp"]="",["slots"]={},["description"]="Max's city-block grid (Gradus ad Parnassum). Base module of every block.\nslot order: Fluid 1; Fluid 2; Universal; Right 2; Right 3; Right 4; Trash"},{["id"]=2,["name"]="CS2 Requester",["source_label"]="[item=requester-chest] CS2 Requester",["source_version"]=1,["icon"]="item/rail",["category"]="Requester",["bp"]="",["slots"]={},["description"]=""},{["id"]=3,["name"]="Bay spine",["source_label"]="Bay spine",["source_version"]=4,["icon"]="item/rail",["category"]="Base Grid",["bp"]="",["slots"]={},["description"]="Bypass track at x = 150 along the right side of the block, with its junctions to the main line every 28 tiles and the connectors at the top and bottom. Needed by every bay on the right side (Universal, Right 2-4, Trash).\nslot order: Fluid 1; Fluid 2; Universal; Right 2; Right 3; Right 4; Trash"},{["id"]=4,["name"]="Exit lane",["source_label"]="Exit lane",["source_version"]=2,["icon"]="item/rail",["category"]="Base Grid",["bp"]="",["slots"]={},["description"]="Exit collector at x = 141 along the right side: the Universal and HT request bays leave their x = 145 track through a curve into this lane, which joins the bottom main line at (125, 155). Needed by the Universal request and the HT solid request. The HT solid provider (Right 4) crosses x = 141 with its belts and cannot share a block with the lane."},{["id"]=5,["name"]="Universal request",["source_label"]="[item=requester-chest] Universal request",["source_version"]=7,["icon"]="item/requester-chest",["category"]="Requester",["bp"]="",["slots"]={{["name"]="Universal",["dx"]=0,["dy"]=0}},["description"]="City-block requester, Cybersyn 2 (Codex's conversion of the block-request design): ghost scanner demand, robot top-up, surplus flush. Stop at (143, 33) facing south on the bay track x = 145.\nslots: Universal = 0,0"},{["id"]=6,["name"]="HT solid request",["source_label"]="[item=steel-chest] HT solid request",["source_version"]=17,["icon"]="item/steel-chest",["category"]="Requester",["bp"]="",["slots"]={{["name"]="Right 2",["dx"]=0,["dy"]=0},{["name"]="Right 3",["dx"]=0,["dy"]=28},{["name"]="Right 4",["dx"]=0,["dy"]=56}},["description"]="High-throughput belt requester, Cybersyn 2: order = the constant on green, chest contents on red (12 steel chests, stack inserters to belts). Authored at Right 2, stop (143, 61) facing south. Includes the entry ladder from the spine above the bay and the exit ladder below it; adjacent bays share these pieces.\nslots: Right 2 = 0,0; Right 3 = 0,28; Right 4 = 0,56"},{["id"]=7,["name"]="HT solid provider",["source_label"]="[item=steel-chest] HT solid provider",["source_version"]=3,["icon"]="item/steel-chest",["category"]="Provider",["bp"]="",["slots"]={{["name"]="Right 4",["dx"]=0,["dy"]=0}},["description"]="High-throughput belt-fed provider, Cybersyn 2: pr = 1 (auto provide all), chest contents on red (12 chests, belts in). Stop (143, 117) facing south. Enters from the spine, leaves south on x = 145 through the Trash band to the bottom connector (those rails are shared with the Trash sender). Its belts cross x = 141, so it does not fit next to the Exit lane.\nslots: Right 4 = 0,0"},{["id"]=8,["name"]="Trash sender",["source_label"]="[item=storage-chest] Trash sender",["source_version"]=6,["icon"]="item/storage-chest",["category"]="Trash",["bp"]="",["slots"]={{["name"]="Trash",["dx"]=0,["dy"]=0}},["description"]="Trash station on the spine itself: stop (149, 141) facing south, 12 storage chests east of the track. Also holds the x = 145 track through this band down to the bottom connector (shared with the HT solid provider).\nslots: Trash = 0,0"},{["id"]=9,["name"]="Fluid request",["source_label"]="[fluid=water] Fluid request",["source_version"]=6,["icon"]="item/storage-tank",["category"]="Requester",["bp"]="",["slots"]={{["name"]="Fluid 1",["dx"]=0,["dy"]=0},{["name"]="Fluid 2",["dx"]=50,["dy"]=0}},["description"]="Tank-bank fluid requester, Cybersyn 2: order = -target on green, tank contents on red on its own siding off the top main line: stop (73, 13) facing east, 8 tanks, 3 pumps. The second fluid slot is the same siding 50 tiles to the right.\nslots: Fluid 1 = 0,0; Fluid 2 = 50,0"},{["id"]=10,["name"]="Provider block (mall)",["source_label"]="[item=passive-provider-chest] Provider block (mall)",["source_version"]=8,["icon"]="item/passive-provider-chest",["category"]="Provider",["bp"]="",["slots"]={},["description"]="Codex's eleven-bay shared-inventory mall (cs2-grid-final, 2026-10-18) as a whole-block module: one master bay and ten slaves on the west side (stops at x = 37), three depot sidings and two [item=storage-chest] Receiver stops on the east side. Infinity chests are the sandbox stock; the sandbox power interfaces were dropped. Starting point for Max's Provider city block."},{["id"]=11,["name"]="Depot",["source_label"]="Depot",["source_version"]=13,["icon"]="item/rail",["category"]="Other",["bp"]="",["slots"]={},["description"]=""},{["id"]=12,["name"]="Depot2",["source_label"]="Depot2",["source_version"]=10,["icon"]="item/rail",["category"]="Other",["bp"]="",["slots"]={},["description"]=""},{["id"]=13,["name"]="Refuel",["source_label"]="Refuel",["source_version"]=5,["icon"]="item/rail",["category"]="Other",["bp"]="",["slots"]={},["description"]=""},{["id"]=14,["name"]="Red",["source_label"]="Red",["source_version"]=2,["icon"]="item/automation-science-pack",["category"]="Other",["bp"]="",["slots"]={{["name"]="Trash",["dx"]=0,["dy"]=0}},["description"]="Trash station on the spine itself: stop (149, 141) facing south, 12 storage chests east of the track. Also holds the x = 145 track through this band down to the bottom connector (shared with the HT solid provider).\nslots: Trash = 0,0"},{["id"]=15,["name"]="New module 1",["source_label"]="New module 1",["source_version"]=2,["icon"]="item/rocket-silo",["c